import test from 'node:test';import assert from 'node:assert/strict';import {buildDemoData} from '../src/demoData.js';import {staffPortal,publishTimetable} from '../src/portal.js';
test('staff response includes only their lessons and excludes internal notes',()=>{const d=buildDemoData();d.publishedTimetable=structuredClone(d.generatedTimetables[0]);d.staff[0].notes='private medical note';const result=staffPortal(d,d.staff[0].id,'2026-10-06');assert.ok(result.master.every(a=>a.teacherId===d.staff[0].id));assert.ok(!JSON.stringify(result).includes('private medical note'));assert.equal(result.role,'staff');});
test('publication blocks impossible timetables',()=>{const d=buildDemoData();d.staff=[];assert.throws(()=>publishTimetable(d),/Resolve/);});
test('approved snapshot remains independent from later draft edits',()=>{const d=buildDemoData();const published=publishTimetable(d),first=published.publishedTimetable.assignments[0];published.generatedTimetables[0].assignments[0].subject='Draft changed';assert.notEqual(first.subject,'Draft changed');assert.ok(published.publicationId);});
// CPD supplies authentication; audit-timetable-security.cjs verifies school/account access.
